C = "Local business & niche"
SPECS = [
 dict(type="S", slug="appointment-reminder-email", category=C, name="Appointment reminder email 24 hours before (cuts no-shows)",
  summary="Emails each client a reminder the day before their appointment, from a simple bookings sheet.",
  tab="Appointments", cols=["client","email","appointment_date","appointment_time","service","reminded"], when="daily 9",
  filter="!has(r.reminded) && daysUntil(r.appointment_date) !== null && daysUntil(r.appointment_date) > 0 && daysUntil(r.appointment_date) <= 1.5",
  mail=dict(to="{email}", subject="Reminder: your appointment tomorrow at {appointment_time}", body="Hi {client},\n\nA reminder of your {service} appointment on {appointment_date} at {appointment_time}. If you need to change it, just reply to this email.\n\n{cfg.business_name}"),
  mark=("reminded","'yes'")),
 dict(type="S", slug="quote-follow-up-trades", category=C, name="Quote follow-up for tradespeople (plumbers, electricians, builders)",
  summary="Follows up on quotes you sent: a polite check-in after 3 days and a last note after 8 days.",
  tab="Quotes", cols=["customer","email","job","quote_amount","sent_date","status","last_follow_up"], when="daily 9",
  filter="String(r.status).toLowerCase() === 'sent' && daysSince(r.sent_date) !== null && daysSince(r.sent_date) >= 3 && (!has(r.last_follow_up) || daysSince(r.last_follow_up) >= 5)",
  mail=dict(to="{email}", subject="Your quote for {job}", body="Hi {customer},\n\nI wanted to check you received my quote of {quote_amount} for {job}. Happy to answer questions or adjust the scope. I have a few slots free this month.\n\n{cfg.sender_name}\n{cfg.business_name}"),
  mark=("last_follow_up","new Date().toISOString().slice(0, 10)")),
 dict(type="I", slug="real-estate-enquiry-responder", category=C, name="Real estate enquiry responder with AI summary and viewing request",
  summary="Collects property enquiries, summarises what the buyer or renter wants, sends them an acknowledgement, and tells the agent.",
  fields=["name","email","phone","property","message"], tab="Property enquiries", trigger="form", form_title="Enquire about this property",
  ai=dict(label="summarise the enquiry", prompt="You help a real estate agent at {cfg.business_name}. Summarise this property enquiry: what they want, budget if given, timeline, and whether they ask for a viewing. Never state prices or availability.",
          schema={"summary":"Wants a viewing this weekend.","wants_viewing":True,"timeline":"This month"}),
  reply=dict(subject="Thanks for your interest in {property}", body="Hi {name},\n\nThanks for asking about {property}. An agent will contact you shortly to arrange a viewing or answer your questions.\n\n{cfg.sender_name}"),
  notify=dict(via="gmail", subject="Property enquiry: {property}", text="{summary}\nViewing requested: {wants_viewing}\nTimeline: {timeline}\n\n{name} {email} {phone}")),
 dict(type="G", slug="restaurant-booking-enquiry-drafts", category=C, name="Restaurant and cafe booking enquiry reply drafts",
  summary="Spots booking enquiries by email, extracts date, time and party size, and saves a friendly reply draft that asks you to confirm.",
  tab="Booking enquiries", query="in:inbox -from:me (booking OR reservation OR table OR book)",
  prompt="You help a restaurant, {cfg.business_name}. Decide if this email asks for a table booking. Extract date, time and party_size (or 'unknown'). Write a short friendly reply draft that thanks them and says you will confirm shortly. Do not confirm availability.",
  schema={"is_booking":True,"date":"Saturday","time":"19:30","party_size":"4","needs_reply":True,"summary":"Table for 4 on Saturday evening.","reply_draft":"Hi ..."},
  alert_when="r.is_booking === true", alert_subject="Booking enquiry: {summary}", alert_body="{date} {time}, party of {party_size}\nFrom {from_address}", draft="reply_draft"),
 dict(type="I", slug="gym-trial-lead-nurture", category=C, name="Gym and studio free-trial signup with welcome email",
  summary="Collects trial signups, sends a welcome with what to bring, and alerts the front desk.",
  fields=["name","email","phone","goal"], tab="Trial signups", trigger="form", form_title="Book your free trial",
  reply=dict(subject="Your free trial is booked, {name}", body="Hi {name},\n\nWelcome! You told us your goal is: {goal}. Bring water, a towel and comfortable clothes. A coach will message you to confirm the time.\n\n{cfg.business_name}"),
  notify=dict(via="gmail", subject="New trial signup: {name}", text="{name} {phone} {email}\nGoal: {goal}")),
 dict(type="S", slug="agency-client-weekly-update", category=C, name="Agency client weekly update reminder to the account manager",
  summary="Every Friday reminds you which clients are due a weekly update, from a client list.",
  tab="Clients", cols=["client","contact_email","last_update_sent","frequency_days"], when="weekly 5 9",
  filter="daysSince(r.last_update_sent) === null || daysSince(r.last_update_sent) >= Number(r.frequency_days || 7)",
  mail=dict(to="{cfg.owner_email}", subject="Update due for {client}", body="{client} ({contact_email}) is due a progress update. Last sent: {last_update_sent}."),
  mark=("last_update_sent","new Date().toISOString().slice(0, 10)"),
  notes="This marks the date when the reminder is sent. If you prefer to mark it yourself after sending, delete the last two nodes."),
 dict(type="I", slug="legal-intake-triage-ai", category=C, name="Legal or consulting intake form with AI triage (no advice given)",
  summary="Collects enquiries for a law or consulting practice, has AI classify the matter type and urgency for the team, and sends the client an acknowledgement. The AI gives no advice.",
  fields=["name","email","phone","matter","details"], tab="Intake", trigger="form", form_title="Tell us about your matter",
  ai=dict(label="triage the matter", prompt="You triage new enquiries for {cfg.business_name}. Classify the matter type (e.g. contract, employment, property, family, other), urgency (low, normal, high) and write a neutral one-sentence summary. Give no legal advice.",
          schema={"matter_type":"employment","urgency":"normal","summary":"Asks about a contract dispute."}),
  reply=dict(subject="We received your enquiry", body="Hi {name},\n\nThank you for contacting {cfg.business_name}. A member of the team will review your enquiry and respond. This message is an acknowledgement and not advice.\n\n{cfg.sender_name}"),
  notify=dict(via="gmail", subject="New intake ({urgency}): {matter_type}", text="{summary}\n\n{name} {email} {phone}\n\n{details}")),
 dict(type="S", slug="candidate-follow-up-recruiter", category=C, name="Recruiter candidate follow-up emails (keep candidates warm)",
  summary="Sends a short status update to candidates who have not heard from you in a week.",
  tab="Candidates", cols=["candidate","email","role","stage","last_contact"], when="daily 10",
  filter="String(r.stage).toLowerCase() !== 'rejected' && String(r.stage).toLowerCase() !== 'hired' && daysSince(r.last_contact) !== null && daysSince(r.last_contact) >= 7",
  mail=dict(to="{email}", subject="Update on your application for {role}", body="Hi {candidate},\n\nA quick update: your application for {role} is still active (stage: {stage}). I will message you as soon as there is news.\n\n{cfg.sender_name}"),
  mark=("last_contact","new Date().toISOString().slice(0, 10)")),
 dict(type="I", slug="event-rsvp-manager", category=C, name="Event RSVP manager with confirmation email and headcount log",
  summary="Guests RSVP through a form, get a confirmation with event details, and the hosts get a live list in a sheet.",
  fields=["name","email","guests","dietary"], tab="RSVPs", trigger="form", form_title="RSVP", cfg=dict(event_name="Our event", event_details="Saturday 6 pm, 12 High Street"),
  reply=dict(subject="You are on the list: {cfg.event_name}", body="Hi {name},\n\nThanks for your RSVP ({guests} guest(s)). Details: {cfg.event_details}. Dietary notes: {dietary}.\n\n{cfg.sender_name}")),
 dict(type="S", slug="coaching-session-reminder-and-followup", category=C, name="Coaching session reminder and follow-up note",
  summary="Reminds clients the day before a session and, the day after, sends a short follow-up asking about their action steps.",
  tab="Sessions", cols=["client","email","session_date","reminded","followed_up"], when="daily 9",
  filter="(!has(r.reminded) && daysUntil(r.session_date) !== null && daysUntil(r.session_date) > 0 && daysUntil(r.session_date) <= 1.5) || (has(r.reminded) && !has(r.followed_up) && daysSince(r.session_date) !== null && daysSince(r.session_date) >= 1)",
  mail=dict(to="{email}", subject="Our session on {session_date}", body="Hi {client},\n\nThis is a note about our session on {session_date}. Before it: jot down your biggest win and your biggest challenge. After it: reply with the one action you will take this week.\n\n{cfg.sender_name}"),
  notes="This version sends the same message for reminder and follow-up; edit the wording to suit, or duplicate the workflow with one rule each."),
 dict(type="I", slug="maintenance-request-triage-ai", category=C, name="Property maintenance request triage with AI urgency",
  summary="Tenants submit a request. AI rates the urgency and trade needed, and you are emailed immediately for emergencies.",
  fields=["name","email","unit","issue"], tab="Maintenance requests", trigger="form", form_title="Report a maintenance issue",
  ai=dict(label="triage the request", prompt="You triage maintenance requests for a property manager. Rate urgency (emergency only for flooding, gas smell, no heating in winter, fire or safety risk; otherwise normal or low) and name the trade needed (plumber, electrician, general, other). One-sentence summary.",
          schema={"urgency":"normal","trade":"plumber","summary":"Dripping tap in the kitchen."}),
  reply=dict(subject="We received your maintenance request", body="Hi {name},\n\nWe logged your request for unit {unit}. If this is an emergency (flood, gas smell, fire) please call the emergency line now.\n\n{cfg.business_name}"),
  notify=dict(when="{urgency} === 'emergency'", via="gmail", subject="EMERGENCY maintenance: unit {unit}", text="{summary}\nTrade: {trade}\n{name} {email}\n\n{issue}")),
 dict(type="I", slug="photographer-booking-and-delivery-emails", category=C, name="Photographer booking enquiry and gallery delivery emails",
  summary="Enquiries are logged and acknowledged. When a shoot is done, send a webhook to email the gallery link.",
  fields=["name","email","shoot_type","date","gallery_link"], tab="Shoots", trigger="form", form_title="Book a shoot",
  reply=dict(subject="Thanks for your enquiry, {name}", body="Hi {name},\n\nThanks for asking about a {shoot_type} shoot on {date}. I will reply with availability and pricing shortly.\n\n{cfg.sender_name}")),
 dict(type="I", slug="course-student-onboarding-emails", category=C, name="Course student onboarding: welcome email and enrolment log",
  summary="When someone enrols (form or payment webhook), they get a welcome email with access details and the enrolment is logged.",
  fields=["name","email","course"], tab="Enrolments", cfg=dict(access_link="https://example.com/course-login"), source_note="Point your checkout or course platform's webhook at the **Webhook** URL (name, email, course).",
  reply=dict(subject="Welcome to {course}", body="Hi {name},\n\nWelcome to {course}! Start here: {cfg.access_link}\n\nReply to this email if you get stuck.\n\n{cfg.sender_name}"),
  notify=dict(via="gmail", subject="New student: {name}", text="{name} <{email}> enrolled in {course}.")),
]
